/**
 * The function catalogue as Markdown (docs/engine-api.md "Public function catalogue"), generated by
 * `pnpm --filter @workspace/player-client gen:catalog` and kept current by test/catalog.test.ts.
 */
import { CATALOG, CATALOG_PATHS, type CatalogEntry } from "./catalog.ts";

export const CATALOG_DOC_BEGIN = "<!-- catalog:begin (generated by `pnpm --filter @workspace/player-client gen:catalog`; do not edit by hand) -->";
export const CATALOG_DOC_END = "<!-- catalog:end -->";

const cell = (text: string) => text.replace(/\|/g, "\\|").replace(/\n/g, " ");

export function catalogMarkdown(): string {
  const lines = [
    "| Function | Kind | Audience | Title | What it does | Assistant tools |",
    "|---|---|---|---|---|---|",
  ];
  for (const path of CATALOG_PATHS) {
    const e: CatalogEntry = CATALOG[path];
    const tools = e.tools.length ? e.tools.map(t => `\`${t}\``).join(", ") : e.why ? `— (${cell(e.why)})` : "—";
    lines.push(`| \`${path}\` | ${e.kind} | ${e.audience} | ${cell(e.human.title)} | ${cell(e.human.tooltip)} | ${tools} |`);
  }
  return lines.join("\n");
}

/** `text` with the generated block replaced (or appended when the markers are missing). */
export function withCatalogDoc(text: string): string {
  const block = `${CATALOG_DOC_BEGIN}\n${catalogMarkdown()}\n${CATALOG_DOC_END}`;
  const start = text.indexOf("<!-- catalog:begin"), end = text.indexOf(CATALOG_DOC_END);
  if (start < 0 || end < 0) return `${text.trimEnd()}\n\n${block}\n`;
  return `${text.slice(0, start)}${block}${text.slice(end + CATALOG_DOC_END.length)}`;
}
